CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), phone VARCHAR(10) UNIQUE NOT NULL CHECK(phone ~ '^[0-9]{10}$'), name TEXT, role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','shop_owner','delivery','admin')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS otp_codes (id BIGSERIAL PRIMARY KEY, phone VARCHAR(10) NOT NULL CHECK(phone ~ '^[0-9]{10}$'), code_hash TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), expires_at TIMESTAMPTZ NOT NULL, consumed_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS otp_codes_phone_created_idx ON otp_codes(phone,created_at DESC);
CREATE TABLE IF NOT EXISTS shops (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id UUID REFERENCES users(id), name_hi TEXT NOT NULL, name_en TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN ('grocery','pharmacy','vegetables','food','electronics','dairy','other')), address TEXT NOT NULL, area TEXT NOT NULL CHECK(area IN ('Dalmau','Murai Bagh')), phone VARCHAR(10), is_open BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS shops_area_open_idx ON shops(area,is_open);
CREATE TABLE IF NOT EXISTS products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), shop_id UUID NOT NULL REFERENCES shops(id) ON DELETE CASCADE, name_hi TEXT NOT NULL, name_en TEXT NOT NULL, description TEXT, price_paise INTEGER NOT NULL CHECK(price_paise>=0), stock_qty INTEGER NOT NULL DEFAULT 0 CHECK(stock_qty>=0), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS products_shop_active_idx ON products(shop_id,active);
CREATE TABLE IF NOT EXISTS orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_number BIGSERIAL UNIQUE, customer_user_id UUID NOT NULL REFERENCES users(id), shop_id UUID NOT NULL REFERENCES shops(id), delivery_user_id UUID REFERENCES users(id), status TEXT NOT NULL DEFAULT 'placed' CHECK(status IN ('placed','accepted','preparing','ready','picked_up','delivered','cancelled')), payment_method TEXT NOT NULL CHECK(payment_method IN ('cash','online')), payment_status TEXT NOT NULL DEFAULT 'pending' CHECK(payment_status IN ('pending','paid','failed','refunded')), subtotal_paise INTEGER NOT NULL CHECK(subtotal_paise>=0), delivery_fee_paise INTEGER NOT NULL DEFAULT 0 CHECK(delivery_fee_paise>=0), total_paise INTEGER NOT NULL CHECK(total_paise>=0), customer_name TEXT NOT NULL, customer_phone VARCHAR(10) NOT NULL CHECK(customer_phone ~ '^[0-9]{10}$'), address TEXT NOT NULL, area TEXT NOT NULL CHECK(area IN ('Dalmau','Murai Bagh')), notes TEXT, razorpay_order_id TEXT UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS orders_customer_created_idx ON orders(customer_user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS orders_delivery_status_idx ON orders(delivery_user_id,status);
CREATE TABLE IF NOT EXISTS order_items (id BIGSERIAL PRIMARY KEY, order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id UUID REFERENCES products(id), product_name_hi TEXT NOT NULL, product_name_en TEXT NOT NULL, unit_price_paise INTEGER NOT NULL CHECK(unit_price_paise>=0), quantity INTEGER NOT NULL CHECK(quantity>0), line_total_paise INTEGER NOT NULL CHECK(line_total_paise>=0));
CREATE TABLE IF NOT EXISTS payment_events (id BIGSERIAL PRIMARY KEY, provider TEXT NOT NULL, provider_event_id TEXT UNIQUE, order_id UUID REFERENCES orders(id), event_type TEXT NOT NULL, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
